def calculate_min_changes(N, A):
    n = 3 ** N
    A = list(map(int, A))

    def flip(i, j, k):
        return [A[i], A[j], A[k]]

    def solve(A, target):
        min_changes = float('inf')
        for i in range(3 ** (N - 1)):
            group = flip(3 * i, 3 * i + 1, 3 * i + 2)
            if sum(group) >= 2:
                new_target = 1
            else:
                new_target = 0
            changes = sum(x != target for x, target in zip(group, [new_target] * 3))
            if changes < 3:
                new_A = A[:]
                for j, val in enumerate(group):
                    new_A[3 * i + j] = val
                min_changes = min(min_changes, changes + solve(new_A, target))
        return min_changes

    return solve(A, 1 - int(A[-1]))

def main():
    N = int(input())
    A = input().strip()
    min_changes = calculate_min_changes(N, A)
    print(min_changes)

