def solve(N, K):
    if N == 0:
        return 0

    pow_list = [1]
    for _ in range(N + 1):
        pow_list.append(pow_list[-1] * 2 % MOD)

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def binom(N, k):
        if k < 0 or k > N:
            return 0
        return (fact[N] * inv_fact[k] * inv_fact[N - k]) % MOD

    dp = [0] * (K + 1)
    dp[1] = binom(N, 1)
    for k in range(2, K + 1):
        dp[k] = (dp[k - 1] * pow(2, N - 1, MOD)) % MOD
        if k > 1:
            dp[k] = (dp[k] + dp[k - 1] * (N - k + 1)) % MOD
        dp[k] = (dp[k] * inv_fact[k]) % MOD

    res = 0
    for k in range(1, K + 1):
        res = (res + dp[k]) % MOD
    return res

