import sys
from collections import defaultdict

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            else:
                self.parent[root_x] = root_y
                if self.rank[root_x] == self.rank[root_y]:
                    self.rank[root_y] += 1

def main():
    N = int(sys.stdin.readline().strip())
    M = int(sys.stdin.readline().strip())
    edges = []
    for i in range(M):
        a, b = map(int, sys.stdin.readline().strip().split())
        a -= 1
        b -= 1
        edges.append((i + 1, a, b))

    uf = UnionFind(N)
    for _, a, b in edges:
        uf.union(a, b)

    components = defaultdict(list)
    for i in range(N):
        root = uf.find(i)
        components[root].append(i)

    if len(components) == 1:
        print(0)
        return

    operations = []
    for i, (cable, a, b) in enumerate(edges):
        if uf.find(a) != uf.find(b):
            root_a = uf.find(a)
            root_b = uf.find(b)
            if len(components[root_a]) > len(components[root_b]):
                operations.append((cable, b + 1, root_a + 1))
                for node in components[root_b]:
                    uf.parent[node] = root_a
                    components[root_a].append(node)
                del components[root_b]
            else:
                operations.append((cable, a + 1, root_b + 1))
                for node in components[root_a]:
                    uf.parent[node] = root_b
                    components[root_b].append(node)
                del components[root_a]

    print(len(operations))
    for op in operations:
        print(*op)

if __name__ == "__main__":
    main()

