import sys

class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, i, delta):
        while i <= self.size:
            self.tree[i] += delta
            i += i & -i

    def query(self, i):
        count = 0
        while i > 0:
            count += self.tree[i]
            i -= i & -i
        return count

    def range_query(self, i, j):
        return self.query(j) - self.query(i - 1)

