class TrieNode:
    def __init__(self):
        self.children = [None, None]
        self.count = 0

def insert(root, num):
    node = root
    for i in range(59, -1, -1):
        bit = (num >> i) & 1
        if node.children[bit] is None:
            node.children[bit] = TrieNode()
        node = node.children[bit]
        node.count += 1

def find_max_xor(root, num, k):
    node = root
    xor = 0
    for i in range(59, -1, -1):
        bit = (num >> i) & 1
        if node.children[1 - bit] is not None and node.children[1 - bit].count >= k:
            xor |= (1 << i)
            node = node.children[1 - bit]
        else:
            node = node.children[bit]
    return xor

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = [int(sys.stdin.readline()) for _ in range(N)]

