    N, X, K = map(int, input().split())
    products = []
    for _ in range(N):
        P, U, C = map(int, input().split())
        products.append((P, U, C))

    dp = [[0] * (X + 1) for _ in range(N + 1)]
    color_count = {}
    for i in range(N):
        _, _, C = products[i]
        color_count[C] = color_count.get(C, 0) + 1

    for i in range(1, N + 1):
        P, U, C = products[i - 1]
        for j in range(1, X + 1):
            if P > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - P] + U + (1 if color_count[C] == 1 else 0) * K)
                if j - P >= 0:
                    for c in range(1, N + 1):
                        if c != C and color_count.get(c, 0) > 0:
                            dp[i][j] = max(dp[i][j], dp[i - 1][j - P] + U + (color_count.get(c, 0) + 1) * K)

    max_satisfaction = 0
    for j in range(X + 1):
        max_satisfaction = max(max_satisfaction, dp[N][j])

    print(max_satisfaction)

