def main():
    input = sys.stdin.readline
    N, X, K = map(int, input().split())
    products = []
    for _ in range(N):
        P, U, C = map(int, input().split())
        products.append((P, U, C))

    # Group products by color
    color_products = {}
    for P, U, C in products:
        if C not in color_products:
            color_products[C] = []
        color_products[C].append((P, U))

    # Dynamic programming
    dp = [-float('inf')] * (X + 1)
    dp[0] = 0

    for C, sub_products in color_products.items():
        new_dp = dp[:]
        for i in range(X + 1):
            if dp[i] != -float('inf'):
                for P, U in sub_products:
                    if i + P > X:
                        continue
                    new_dp[i + P] = max(new_dp[i + P], dp[i] + U)
        dp = new_dp

    max_satisfaction = 0
    for i in range(X + 1):
        T = len([C for C in color_products if any(P <= i for P, _ in color_products[C])])
        satisfaction = dp[i] + T * K
        max_satisfaction = max(max_satisfaction, satisfaction)

    print(max_satisfaction)

if __name__ == '__main__':
