from math import sqrt
from collections import defaultdict

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def is_square(n):
    if n < 0:
        return False
    sqrt_n = sqrt(n)
    return sqrt_n == int(sqrt_n)

def main():
    N = int(sys.stdin.readline().strip())
    a = []
    b = []
    c = []
    for _ in range(N-1):
        a.append(list(map(int, sys.stdin.readline().strip().split())))
    for _ in range(N-1):
        b.append(list(map(int, sys.stdin.readline().strip().split())))
    for _ in range(N-1):
        c.append(list(map(int, sys.stdin.readline().strip().split())))

