    for i in range(N):
        for j in range(i+1):
            if i > 0:
                factors[(i, j, i-1, j)] = prime_factors(a[i-1][j])
            if i > 0 and j < i:
                factors[(i, j, i-1, j+1)] = prime_factors(b[i-1][j])
            if i > 1 and j < i-1:
                factors[(i, j, i-1, j)] = prime_factors(c[i-1][j])

    count = 0
    for s in range(N*(N+1)//2):
        for t in range(s+1, N*(N+1)//2):
