from math import sqrt
from collections import defaultdict

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def is_square(n):
    if n < 0:
        return False
    sqrt_n = sqrt(n)
    return sqrt_n == int(sqrt_n)

