    N = int(sys.stdin.readline().strip())
    a = []
    b = []
    c = []
    for _ in range(N-1):
        a.append(list(map(int, sys.stdin.readline().strip().split())))    for _ in range(N-1):
        b.append(list(map(int, sys.stdin.readline().strip().split())))    for _ in range(N-1):
        c.append(list(map(int, sys.stdin.readline().strip().split())))

    factors = {}
    for i in range(N):
        for j in range(i+1):
            if i > 0:
                factors[(i, j, i-1, j)] = prime_factors(a[i-1][j])
            if i > 0 and j < i:
                factors[(i, j, i-1, j+1)] = prime_factors(b[i-1][j])
            if i > 1 and j < i-1:
                factors[(i, j, i-1, j)] = prime_factors(c[i-1][j])

    count = 0
    vertex_list = []
    for i in range(N):
        for j in range(i+1):
            vertex_list.append((i, j))
    for s in range(len(vertex_list)):
        for t in range(s+1, len(vertex_list)):
            s_coords = vertex_list[s]
            t_coords = vertex_list[t]
            path_factors = []
            if s_coords[0] < t_coords[0]:
                for i in range(s_coords[0], t_coords[0]):
                    if s_coords[1] <= t_coords[1] <= s_coords[0] + (t_coords[0] - s_coords[0]):
                        if s_coords[1] == t_coords[1]:
                            path_factors.extend(factors[(i+1, s_coords[1], i, s_coords[1])])
                        if s_coords[1] < t_coords[1]:
                            path_factors.extend(factors[(i+1, s_coords[1]+1, i, s_coords[1])])
            else:
                continue
            product = 1
            factor_counts = defaultdict(int)
