import sys

def can_transform(K, S, T):
    """
    Determine whether it is possible to perform the given operations on string S
    between 0 and K times, inclusive, to make it identical to string T.
    """
    i, j = 0, 0
    operations = 0

    while i < len(S) and j < len(T):
        if S[i] != T[j]:
            operations += 1
            if operations > K:
                return False
            j += 1
        else:
            i += 1
            j += 1

    # If we have remaining characters in S, we need to delete them
    while i < len(S):
        operations += 1
        if operations > K:
            return False
        i += 1

    # If we have remaining characters in T, we need to insert them
    while j < len(T):
        operations += 1
        if operations > K:
            return False
        j += 1

    return True

def main():
    K = int(sys.stdin.readline().strip())
    S = sys.stdin.readline().strip()
    T = sys.stdin.readline().strip()

    if can_transform(K, S, T):
        print("Yes")
    else:
        print("No")

