from collections import deque

def bfs(grid, start, destroyed_walls):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    height, width = len(grid), len(grid[0])
    queue = deque([(start, destroyed_walls)])
    visited = {(start, destroyed_walls)}
    count = 0

    while queue:
        (x, y), dw = queue.popleft()
        count += 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < height and 0 <= ny < width and
                    (nx, ny, dw) not in visited):
                cell = grid[nx][ny]
                if cell == '#':
                    if dw == 0:
                        queue.append(((nx, ny), 1))
                        visited.add((nx, ny, 1))
                    else:
                        continue
                else:
                    queue.append(((nx, ny), dw))
                    visited.add((nx, ny, dw))

    return count

def solve():
    height, width = map(int, input().split())
    grid = []
    start = None

    for _ in range(height):
        row = list(input())
        grid.append(row)
        if 'S' in row:
            start = (len(grid) - 1, row.index('S'))

    print(bfs(grid, start, 0))

if __name__ == "__main__":
    solve()

