def can_transform(A, B, K):
    N = len(A)
    count = defaultdict(int)
    for a, b in zip(A, B):
        if a != b:
            count[a] += 1
            count[b] -= 1
    for i in range(N):
        if count[A[i]] > 0 and not can_reach(i, A, B, K):
            return False
    return True

def can_reach(i, A, B, K):
    N = len(A)
    target = B[i]
    visited = [False] * N
    stack = [i]
    visited[i] = True
    while stack:
        node = stack.pop()
        if A[node] == target:
            return True
        for j in range(max(0, node - K), min(N, node + K + 1)):
            if not visited[j] and A[j] == A[node]:
                stack.append(j)
                visited[j] = True
    return False

