from collections import Counter, deque

def can_transform(A, B, K):
    N = len(A)
    # Count occurrences of each value in A and B
    count_A = Counter(A)
    count_B = Counter(B)
    # If the counts are not equal, it's impossible to transform A into B
    if count_A != count_B:
        return False
    # Initialize graph for BFS
    graph = [[] for _ in range(N)]
    for i in range(N):
        for j in range(max(0, i - K), min(N, i + K + 1)):
            if i != j and A[i] == A[j]:
                graph[i].append(j)
    # Perform BFS for each index where A[i] != B[i]
    for i in range(N):
        if A[i] != B[i]:
            found = False
            queue = deque([i])
            visited = [False] * N
            visited[i] = True
            while queue:
                node = queue.popleft()
                if A[node] == B[i]:
                    found = True
                    break
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
                        visited[neighbor] = True
            if not found:
                return False
    return True

