    N = int(sys.stdin.readline().strip())
    A = list(map(int, sys.stdin.readline().strip().split()))

    pos_sum = [0] * (N + 1)
    neg_sum = [0] * (N + 1)
    for i in range(N):
        pos_sum[i + 1] = pos_sum[i] + max(A[i], 0)
        neg_sum[i + 1] = neg_sum[i] + min(A[i], 0)

    ans = 1
    for i in range(N):
        if A[i] > 0:
            ans = (ans * (pos_sum[i + 1] + 1)) % MOD
        elif A[i] < 0:
            ans = (ans * (neg_sum[i + 1] + 1)) % MOD
        else:
            ans = (ans * 2) % MOD

    print(ans)

