def min_operations(A):
    N = len(A)
    memo = {}

    def dp(start):
        if start == N:
            return 0
        if start in memo:
            return memo[start]

        # Try to delete
        current = A[start]
        i = start
        while i < N and A[i] == current:
            i += 1
        if i != start:
            delete_ops = i - start + dp(i)
            result = min(delete_ops, float('inf'))
        else:
            result = float('inf')

        # Swap with next
        if start < N - 1:
            A[start], A[start + 1] = A[start + 1], A[start]
            swap_ops = 1 + dp(start + 1)
            A[start], A[start + 1] = A[start + 1], A[start]
            result = min(result, swap_ops)

        memo[start] = result
        return result

    return dp(0)

