from collections import Counter

def min_cost(N, C, S):
    lang_counts = Counter(S)
    total_cost_translator = sum(i * (i + 1) // 2 for i in lang_counts.values())

    sorted_langs = sorted(lang_counts.values(), reverse=True)
    cumulative_sum = [0] * (len(sorted_langs) + 1)
    for i in range(len(sorted_langs)):
        cumulative_sum[i + 1] = cumulative_sum[i] + sorted_langs[i]

    min_cost = total_cost_translator
    for i in range(len(sorted_langs)):
        learn_cost = C + sum(j * (j + 1) // 2 for j in range(1, N - cumulative_sum[i + 1] + 1))
        min_cost = min(min_cost, learn_cost)

    return min(min_cost, total_cost_translator)

def main():
