    def findMaximumNumber(self, k: int, x: int) -> int:
        def get_price(num):
            price = 0
            i = x
            while i <= num.bit_length():
                price += (num >> (i - 1)) & 1
                i += x
            return price

        left, right = 1, 2 ** 60
        while left < right:
            mid = (left + right + 1) // 2
            accumulated_price = 0
            for i in range(1, mid + 1):
                accumulated_price += get_price(i)
                if accumulated_price > k:
                    break
            if accumulated_price <= k:
                left = mid
            else:
                right = mid - 1
        return left

