        if k > n:
            return 0
        numerator = 1
        denominator = 1
        for i in range(k):
            numerator = (numerator * (n - i)) % mod
            denominator = (denominator * (i + 1)) % mod
        return (numerator * pow(denominator, mod - 2, mod)) % mod

    def pow_list(base, max_pow, mod):
        pow_list = [1]
        for _ in range(max_pow):
            pow_list.append((pow_list[-1] * base) % mod)
        return pow_list

