import sys

def solve(n, s1, s2, s3):
    ones = [s.count('1') for s in [s1, s2, s3]]
    zeros = [s.count('0') for s in [s1, s2, s3]]

    total_ones = sum(ones)
    total_zeros = sum(zeros)

    if total_ones % 3 != 0 and total_zeros % 3 != 0:
        return "-1"
    if total_ones % 3 == 0:
        target = total_ones // 3
        operations = sum(abs(x - target) for x in ones) // 2
        return str(operations)
    else:
        target = total_zeros // 3
        operations = sum(abs(x - target) for x in zeros) // 2
        return str(operations)

def main():
    try:
        t = int(sys.stdin.readline().strip())
        for _ in range(t):
            n = int(sys.stdin.readline().strip())
            s1 = sys.stdin.readline().strip()
            s2 = sys.stdin.readline().strip()
            s3 = sys.stdin.readline().strip()
            sys.stdout.write(solve(n, s1, s2, s3) + "\n")
    except Exception as e:
        pass

if __name__ == "__main__":
    main()

