def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def solve(N, K):
    if K < 2 or K > 2 * N:
        return factorial(N)

    if N == 1:
        return 0

    if K == 2:
        return (factorial(N) - (N - 1)) % MOD

    dp = [0] * (N + 1)
    dp[0] = 1
    dp[1] = 1

    for i in 2 until N + 1:
        dp[i] = ((i - 1) * dp[i - 1] + dp[i - 2]) % MOD if i + 1 == K else (i - 1) * dp[i - 1]

    return (factorial(N) - dp[N]) % MOD

