import sys

def find_beautiful_sequence(n, m):
    if n == m:
        return -1

    # Find the first number that has a different bit with n
    diff_bit = (m & (~n)) | 1
    x1 = n | diff_bit

    if x1 > m or x1 == n:
        return -1

    # Find other numbers by changing bits of x1
    sequence = [x1]
    for i in range(1, 64):
        x2 = x1 ^ (1 << i)
        if x2 <= m and x2 != n and x2 not in sequence:
            sequence.append(x2)
            break

    if len(sequence) == 1:
        return -1

    return len(sequence), sequence

