def find_longest_beautiful_sequence(n, m):
    if n == m:
        return -1

    # Find the largest y such that y & (~n) != 0 and n | y <= m
    left, right = 0, m - n
    while left < right:
        mid = (left + right + 1) // 2
        if (mid & (~n)) != 0 and (n | mid) <= m:
            left = mid
        else:
            right = mid - 1

    y = left
    if y == 0 or (n | y) > m or (n | y) == n:
        return -1

    sequence = [n | y, n]
    return len(sequence), sequence

