class Solution:
    def __init__(self):
        self.mod = 10**9 + 7
        self.max_n = 10**6 + 10
        self.factorials = [1] * (self.max_n + 1)
        self.inverse_factorials = [1] * (self.max_n + 1)
        self.inverses = [1] * (self.max_n + 1)
        self._build_factorials()

    def _build_factorials(self):
        for i in range(2, self.max_n + 1):
            self.factorials[i] = self.factorials[i-1] * i % self.mod
            self.inverses[i] = self.mod - self.mod // i * self.inverses[self.mod % i] % self.mod
            self.inverse_factorials[i] = self.inverse_factorials[i-1] * self.inverses[i] % self.mod

    def comb(self, n, r):
        if r < 0 or r > n:
            return 0
        return self.factorials[n] * self.inverse_factorials[r] * self.inverse_factorials[n-r] % self.mod

    def distributeCandies(self, n: int, limit: int) -> int:
        res = 0
        for i in range(min(n, limit) + 1):
            for j in range(min(n - i, limit) + 1):
                k = n - i - j
                if k <= limit and k >= 0:
                    res += self.perm_count(i, j, k)
        return res % self.mod

    def perm_count(self, a, b, c):
        if a == b == c:
            return 1
        elif a == b or b == c or c == a:
            return 3
        else:
            return 6

