        l1, l2, l3 = len(s1), len(s2), len(s3)
        min_len = min(l1, l2, l3)
        for i in range(min_len):
            if s1[-1 - i] != s2[-1 - i] or s1[-1 - i] != s3[-1 - i]:
                return -1
        return l1 + l2 + l3 - 3 * min_len

