import heapq

def solve(N, X, A, B):
    win_states = 0
    lose_states = []
    for i in range(N):
        if A[i] > B[i]:
            win_states += 1
        else:
            heapq.heappush(lose_states, (B[i] - A[i] + 1, i))

    if win_states > N // 2:
        return "YES"

    while lose_states and X > 0:
        diff, i = heapq.heappop(lose_states)
        if X >= diff:
            X -= diff
            A[i] += diff
            if A[i] > B[i]:
                win_states += 1
        else:
            break

    if win_states > N // 2:
        return "YES"
    else:
        return "NO"

