class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        # Sort the coins array
        coins.sort()

        # Initialize a boolean array dp of size target + 1
        dp = [False] * (target + 1)
        dp[0] = True

        # Iterate over coins and update dp
        for coin in coins:
            for i in range(coin, target + 1):
                dp[i] = dp[i] or dp[i - coin]

        # Count the minimum number of coins needed
        res = 0
        cur = 0
        for i in range(1, target + 1):
            if dp[i]:
                cur = i
            else:
                res += 1
                cur = i
        return res

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        obtainable = {0}
        for coin in coins:
            new_obtainable = {x + coin for x in obtainable if x + coin <= target}
            obtainable |= new_obtainable
        res = 0
        cur = 0
        for i in range(1, target + 1):
            if i in obtainable:
                cur = i
            else:
                res += 1
                cur = i
        return res

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        res = 0
        cur = 0

        for coin in coins:
            if coin > cur + 1:
                res += (cur + 1 - coin) // coin
                cur += 1 + (cur + 1 - coin) // coin * coin
            cur = max(cur, coin)

        if cur < target:
            res += (target - cur + cur) // (cur + 1)

        return res

