    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        mod = 10**9 + 7
        m = len(sick)
        left, right = [1]*(m+1), [1]*(m+1)
        fac = [1] * (n + 1)
        inv = [1] * (n + 1)

        # Precompute factorials and inverses mod 10^9 + 7
