                left[i] = fac[sick[i-1]] * inv[sick[i-1] + 1] % mod
            else:
                left[i] = fac[sick[i-1] - sick[i-2]] * inv[sick[i-1] - sick[i-2] + 1] % mod

        for i in range(m-1, -1, -1):
            if i == m-1:
                right[i] = fac[n - 1 - sick[i]] * inv[n - sick[i]] % mod
            else:
                right[i] = fac[n - 1 - sick[i] - (n - 1 - sick[i+1])] * inv[n - 1 - sick[i] - (n - 1 - sick[i+1]) + 1] % mod

        res = 1
        for i in range(m):
            res = res * left[i+1] * right[i] % mod
        return res

