def is_smoothly_increasing(arr: List[int]) -> bool:
    """
    Check if the given array is smoothly increasing.

    Args:
    arr (List[int]): The input array.

    Returns:
    bool: True if the array is smoothly increasing, False otherwise.
    """
    if len(arr) <= 1:
        return True

    # Check if the array is strictly increasing
    if not all(arr[i] < arr[i + 1] for i in range(len(arr) - 1)):
        return False

    # Calculate the difference array
    diff_arr = [arr[i + 1] - arr[i] for i in range(len(arr) - 1)]

    # Check if the difference array is smoothly increasing
    return is_smoothly_increasing(diff_arr)


def solve(arr: List[int]) -> str:
    """
    Solve the problem for the given array.

    Args:
    arr (List[int]): The input array.

    Returns:
    str: A binary string indicating whether deleting each element results in a smoothly increasing array.
    """
    n = len(arr)
    result = ['0'] * n

    # Check if the array is smoothly increasing
    if is_smoothly_increasing(arr):
        result = ['1'] * n

    # If not, check for each element
    for i in range(n):
        if i == 0:
