        ans = numBottles
        empty_bottles = numBottles
        while empty_bottles >= numExchange:
            new_bottles = empty_bottles // numExchange
            empty_bottles = new_bottles + (empty_bottles % numExchange)
            numExchange += 1
            ans += new_bottles
        return ans

