class Solution:
    def minimumPushes(self, word: str) -> int:
        # Create a histogram of character frequencies in the word
        freq = {char: 1 for char in word}

        # Sort the characters by frequency in descending order
        sorted_chars = sorted(freq.items(), key=lambda x: x[1], reverse=True)

        # Initialize the total pushes to 0
        total_pushes = 0

        # Assign characters to keys using a greedy strategy
        for i, (char, count) in enumerate(sorted_chars):
            total_pushes += count * (i % 9 + 1)

        return total_pushes

