class Solution:
    def minOperations(self, k: int) -> int:
        if k <= 1:
            return 0

        # Calculate the optimal number of duplications and increments
        x = math.ceil(math.sqrt(k))
        # Adjust x if it results in a sum less than k when duplicated
        if x * x < k:
            x += 1

        # Calculate the minimum number of operations
        return x - 1 + math.ceil(math.log2(k / x))

