class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        # Precompute the count of set bits for each number
        set_bits = [bin(num).count('1') for num in nums]

        # Group numbers by the count of their set bits
        groups = {}
        for i, (num, bits) in enumerate(zip(nums, set_bits)):
            if bits not in groups:
                groups[bits] = []
            groups[bits].append((num, i))

        # Sort each group
        for bits in groups:
