    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        can_mark = [False] * n
        earliest_mark = [float('inf')] * n
        earliest_zero = [float('inf')] * n

        for s in range(m):
            idx = changeIndices[s] - 1
            earliest_mark[idx] = min(earliest_mark[idx], s)
            if nums[idx] == 0:
                can_mark[idx] = True

        for i in range(n):
            if nums[i] > 0:
                earliest_zero[i] = nums[i]

        dp = [float('inf')] * (m + 1)
        dp[0] = 0

        for s in range(m):
            dp[s + 1] = min(dp[s + 1], dp[s] + 1)
            idx = changeIndices[s] - 1
            if earliest_mark[idx] == s:
                if can_mark[idx]:
                    dp[s + 1] = min(dp[s + 1], dp[s])
                else:
                    remaining = nums[idx] - (dp[s + 1] - dp[s])
                    if remaining >= 0:
                        dp[s + 1] = min(dp[s + 1], dp[s] + remaining)

        for i in range(n):
            if not can_mark[i]:
                return -1

        return dp[m] if dp[m] <= m else -1

