    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n, m = len(nums), len(pattern)
        count = 0
        diffs = [0] * (n - 1)
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                diffs[i] = 1
            elif nums[i + 1] < nums[i]:
                diffs[i] = -1
            else:
                diffs[i] = 0

        prefix_sum = [0] * (n - 1)
        prefix_sum[0] = diffs[0]
        for i in range(1, n - 1):
            prefix_sum[i] = prefix_sum[i - 1] + diffs[i]

        pattern_sum = 0
        for p in pattern:
            pattern_sum += p

        for i in range(m - 1, n - 1):
            if i >= m and prefix_sum[i] - prefix_sum[i - m] == pattern_sum:
                count += 1
            elif i < m - 1 and prefix_sum[i] == pattern_sum:
                count += 1
        return count

