class Solution:
    def compute_prefix_function(self, pattern: str) -> List[int]:
        """Compute the prefix function used in KMP algorithm."""
        prefix = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j > 0 and pattern[j] != pattern[i]:
                j = prefix[j - 1]
            if pattern[j] == pattern[i]:
                j += 1
            prefix[i] = j
        return prefix

    def kmp_search(self, text: str, pattern: str) -> List[int]:
        """Find all occurrences of pattern in text using KMP algorithm."""
        prefix = self.compute_prefix_function(pattern)
        indices = []
        j = 0
        for i in range(len(text)):
            while j > 0 and text[i] != pattern[j]:
                j = prefix[j - 1]
            if text[i] == pattern[j]:
                j += 1
            if j == len(pattern):
                indices.append(i - len(pattern) + 1)
                j = prefix[j - 1]
        return indices

    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        """Find beautiful indices in string s."""
        a_indices = self.kmp_search(s, a)
        b_indices = self.kmp_search(s, b)

        result = []
        b_index_set = set(b_indices)
        for i in a_indices:
            if any(abs(i - j) <= k for j in b_index_set):
                result.append(i)
        return sorted(result)

