class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        id_count = defaultdict(int)
        max_heap = []
        ans = []

        for i in range(len(nums)):
            id_count[nums[i]] += freq[i]

            # Remove outdated entries from the heap
            while max_heap and max_heap[0][1] != id_count[max_heap[0][0]]:
                heapq.heappop(max_heap)

            # If the count of an ID becomes 0, it might be removed from the heap
            if id_count[nums[i]] == 0:
                if max_heap and max_heap[0][0] == nums[i]:
                    heapq.heappop(max_heap)

            # Push or update the count of the current ID into the heap
            if id_count[nums[i]] > 0:
                heapq.heappush(max_heap, (-id_count[nums[i]], nums[i]))

            # The max count is the top of the heap
            if max_heap:
                ans.append(-max_heap[0][0])
            else:
                ans.append(0)
        return ans

