            count_map = {}
            unique_count = 0
            left_ptr = 0

            for right_ptr in range(n):
                count_map[nums[right_ptr]] = count_map.get(nums[right_ptr], 0) + 1
                while len(count_map) > mid:
                    count_map[nums[left_ptr]] -= 1
                    if count_map[nums[left_ptr]] == 0:
                        del count_map[nums[left_ptr]]
                    left_ptr += 1
                unique_count += right_ptr - left_ptr + 1
            return unique_count

        while left < right:
            mid = (left + right) // 2
            if check(mid) < (n * (n + 1)) // 2 // 2:
                left = mid + 1
            else:
                right = mid
        return left

