        for employee, times in employee_access_times.items():
            if len(times) < 3:
                continue

            times.sort()
            window_start = 0
            for window_end in range(len(times)):
                while times[window_end] - times[window_start] >= 100:
                    window_start += 1
                if window_end - window_start + 1 >= 3:
                    high_access_employees.add(employee)
                    break

        return list(high_access_employees)

