class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        def orientation(p: List[int], q: List[int], r: List[int]) -> int:
            val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
            if val == 0:
                return 0  # Collinear
            elif val > 0:
                return 1  # Clockwise
            else:
                return 2  # Counterclockwise

        def convex_hull(points: List[List[int]]) -> List[List[int]]:
            n = len(points)
            if n < 3:
                raise ValueError("Convex hull not possible")

            hull = []
            l = 0
            for i in range(1, n):
                if points[i][0] < points[l][0]:
                    l = i

            p = l
            q = 0
            while True:
                hull.append(points[p])
                q = (p + 1) % n

                for i in range(n):
                    if orientation(points[p], points[i], points[q]) == 2:
                        q = i

                p = q
                if p == l:
                    break

            return hull

        def max_distance(points: List[List[int]]) -> int:
            max_dist = 0
            for i in range(len(points)):
                for j in range(i + 1, len(points)):
                    dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
                    max_dist = max(max_dist, dist)
            return max_dist

        hull = convex_hull(points)
        max_dist = max_distance(hull)

        res = float('inf')
        for p in hull:
            temp_max_dist = 0
            for other in hull:
                if p != other:
                    temp_dist = abs(p[0] - other[0]) + abs(p[1] - other[1])
                    temp_max_dist = max(temp_max_dist, temp_dist)
            res = min(res, temp_max_dist)
        return res

