    def minCostToEqualizeArray(self, nums: List[int], cost1: int, cost2: int) -> int:
        MOD = 10**9 + 7
        mx = max(nums)
        n = len(nums)

        if cost2 >= 2 * cost1:
            return (sum(mx - num for num in nums) * cost1) % MOD

        diff_odd = diff_even = 0
        for num in nums:
            diff = mx - num
            if diff % 2 == 0:
                diff_even += diff
            else:
                diff_odd += diff

        ans = (diff_even // 2 * cost2 + diff_odd * cost1) % MOD
        if diff_odd:
            ans = min(ans, (diff_even // 2 * cost2 + (diff_odd - 1) * cost1 + cost2) % MOD)
        return ans

class Solution:
    def minCostToEqualizeArray(self, nums, cost1, cost2):
        MOD = 10**9 + 7
        n = len(nums)
        mx = max(nums)
        total_cost = 0
        nums.sort()
        for i in range(n):
            diff = mx - nums[i]
            if diff % 2 == 0:
                total_cost += min(cost1 * diff, cost2 * (diff // 2))
            else:
                total_cost += min(cost1 * diff, cost2 * (diff // 2) + cost1)
        return total_cost % MOD

