class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Initialize dp table
        dp = [[0]*n for _ in range(m)]

        # Base case: first row
        for j in range(n):
            if j > 0 and grid[0][j] == grid[0][j-1]:
                dp[0][j] = 1

        # Fill up dp table
        for i in range(1, m):
            for j in range(n):
                # Check if current cell is equal to the cell below it
                if i > 0 and grid[i][j] == grid[i-1][j]:
                    dp[i][j] = dp[i-1][j] + 1
                # Check if current cell is different from the cell to its right
                if j > 0 and grid[i][j] == grid[i][j-1]:
                    dp[i][j] = max(dp[i][j], dp[i][j-1] + 1)

        # Compute minimum number of operations needed
        res = 0
        for j in range(n):
            res += min(dp[-1][j], 1)

        return res

