        smallest_char = 'z' + '1'
        for c in s:
            if c != '*':
                stack.append(c)
                smallest_char = min(smallest_char, c)
            elif stack and stack[-1] != smallest_char:
                idx = stack.index(smallest_char)
                stack.pop(idx)
                smallest_char = 'z' + '1'
                for c in stack:
                    smallest_char = min(smallest_char, c)
            elif stack:
                stack.pop()
        return ''.join(stack)

