            graph[v].append((u, length))

        # Initialize distance and priority queue
        distance = [float('inf')] * n
        distance[0] = 0

        pq = [(0, 0)]  # (dist, node)

        while pq:
            curr_dist, curr_node = heapq.heappop(pq)
            if curr_dist > distance[curr_node]:
                continue
            if curr_dist > disappear[curr_node]:
                continue
            for neighbor, weight in graph[curr_node]:
                new_dist = curr_dist + weight
                if new_dist < distance[neighbor] and new_dist <= disappear[neighbor]:
                    distance[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))

        return [-1 if dist == float('inf') else dist for dist in distance]

