class Solution:
    def findPermutation(self, nums: List[int]) -> List[int]:
        n = len(nums)
        indegree = [0] * n
        for num in nums:
            indegree[num] += 1

        stack = [i for i in range(n) if indegree[i] == 0]
        res = []
        while stack:
            node = stack.pop()
            res.append(node)
            indegree[node] -= 1
            if nums[node] not in res and indegree[nums[node]] == 0:
                stack.append(nums[node])
            elif indegree[nums[node]] == 0:
                stack.append(nums[node])

        # find lexicographically smallest permutation with min score
        min_score = float('inf')
        min_perm = None
        def backtrack(path, used):
            nonlocal min_score, min_perm
            if len(path) == n:
                score = sum(abs(path[i] - nums[path[(i + 1) % n]]) for i in range(n))
                if score < min_score:
                    min_score = score
                    min_perm = path[:]
                elif score == min_score and path < min_perm:
                    min_perm = path[:]
                return
            for i in range(n):
                if not used[i]:
                    used[i] = True
                    path.append(i)
                    backtrack(path, used)
                    path.pop()
                    used[i] = False

        used = [False] * n
        backtrack([], used)
        return min_perm

