class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], k: int) -> int:
        n = len(colors)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + (colors[i] != colors[(i - 1) % n])

        count = 0
        for i in range(n):
            if i + k - 1 >= n:
                break
            changes = prefix_sum[i + k] - prefix_sum[i]
            if changes == k - 1:
                count += 1

        for i in range(n - k + 1):
            changes = prefix_sum[n] - prefix_sum[i] + prefix_sum[i + k - n]
            if changes == k - 1:
                count += 1
        return count

