    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        big_nums = []
        x = 1
        while len(big_nums) < 1016:
            powerful_array = []
            temp = x
            i = 0
            while temp > 0:
                if temp & 1:
                    powerful_array.append(2 ** i)
                i += 1
                temp >>= 1
            big_nums.extend(powerful_array)
            x += 1

        ans = []
        for query in queries:
            fromi, toi, modi = query
            product = 1
            for num in big_nums[fromi-1:toi]:
                product = (product * num) % modi
            ans.append(product)
        return ans

