        mid = (start + end) // 2
        if idx <= mid:
            self.update(2 * node, start, mid, idx, val)
        else:
            self.update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node][0] = max(self.tree[2 * node][0], self.tree[2 * node + 1][1] + self.tree[2 * node + 1][0])
