class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for si, ti in zip(s, t):
            s_index = ord(si) - ord('a')
            t_index = ord(ti) - ord('a')
            if s_index == t_index:
                continue

            distance = (t_index - s_index) % 26
            total_cost += min(nextCost[s_index] * distance, previousCost[s_index] * (26 - distance))
        return total_cost

