                    ancestor[node] = parent[node]
                else:
                    ancestor[node] = ancestor[parent[node]]
            for child in graph[node]:
                stack.append(child)

        # Rebuild graph with new parents
        new_graph = [[] for _ in range(n)]
        for i in range(1, n):
            if ancestor[i] != -1:
                new_graph[ancestor[i]].append(i)
