class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        length = 1
        for op in operations:
            if op == 0:
                length *= 2
            else:
                length += length

        def find_kth(k, operations, current_word="a"):
            if not operations:
                return current_word[k - 1]
            op = operations[0]
            if op == 0:
                half_length = len(current_word)
                if k <= half_length:
                    return find_kth(k, operations[1:], current_word)
                else:
                    return find_kth(k - half_length, operations[1:], current_word)
            else:
                new_word = ""
                for char in current_word:
                    new_char = chr((ord(char) - ord('a') + 1) % 26 + ord('a'))
                    new_word += char + new_char
                if k <= len(current_word):
                    return find_kth(k, operations[1:], current_word)
                else:
                    return find_kth(k - len(current_word), operations[1:], new_word)

        return find_kth(k, operations)

