class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])

        # Find the maximum value in each row and store them with their row indices.
        row_max = [(max(row), i) for i, row in enumerate(board)]

        # Find the maximum value in each column and store them with their column indices.
        col_max = [(max(col), j) for j, col in enumerate(zip(*board))]

        # Sort the row and column maximums in descending order.
        row_max.sort(reverse=True)
        col_max.sort(reverse=True)

        # Select the top 3 unique cells.
        selected = set()
        total_sum = 0
        for _, i in row_max[:3]:
            for j in range(n):
                if board[i][j] == row_max[i]:
                    selected.add((i, j))
                    total_sum += board[i][j]
                    break

        for _, j in col_max[:3]:
            if (i, j) not in selected:
                for i in range(m):
                    if board[i][j] == col_max[j]:
                        total_sum += board[i][j]
                        break

        return total_sum

