class Solution:
    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        nums.sort()
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right + 1) // 2
            if canAchieve(nums, k, numOperations, mid):
                left = mid
            else:
                right = mid - 1
        return left

def canAchieve(nums: List[int], k: int, numOperations: int, freq: int) -> bool:
    window_sum = 0
    for i in range(len(nums)):
        window_sum += nums[i]
        if i >= freq:
            window_sum -= nums[i - freq]
        if i >= freq - 1:
            target_sum = nums[i] * freq
            if target_sum - window_sum <= numOperations * k:
                return True
    return False

