class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [[0]*3 for _ in range(n+1)]
        dp[0][0] = dp[0][1] = dp[0][2] = 1

        for i in range(1, n+1):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        if (s[i-1] == 'F' and k == 2) or (s[i-1] == 'W' and k == 0) or (s[i-1] == 'E' and k == 1):
                            dp[i][j] = (dp[i][j] + dp[i-1][k]) % MOD

        return sum(dp[n]) % MOD

