        intervals = sorted((i, x, y) for i, (x, y, z) in enumerate(intervals))
        n = len(intervals)
        dp = [[-1, -1, -1, -1] for _ in range(n)]
        dp[0] = [intervals[0][1], intervals[0][2], intervals[0][0]]

        for i in range(1, n):
            dp[i][0] = max(dp[i-1][0], intervals[i][1])
            dp[i][1] = max(dp[i-1][1], intervals[i][2])
            dp[i][2] = intervals[i][0]
            if intervals[i][0] > dp[i-1][0]:
                dp[i][3] = i
            else:
                dp[i][3] = dp[i-1][3]

        max_weight = 0
        max_indices = []
        for i in range(n):
            for j in range(i+1, n):
                if intervals[j][0] <= intervals[i][1]:
                    continue
                weight = intervals[i][2] + intervals[j][2]
                if weight > max_weight:
                    max_weight = weight
                    max_indices = [intervals[i][3], intervals[j][3]]

        for i in range(n):
