                        weight = intervals[i][2] + intervals[j][2] + intervals[k][2] + intervals[last][2]
                        if weight > max_weight:
                            max_weight = weight
                            max_indices = [intervals[i][3], intervals[j][3], intervals[k][3], intervals[last][3]]
        return sorted(max_indices)

