class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        def is_k_palindromic(num: int, k: int) -> bool:
            return str(num) == str(num)[::-1] and num % k == 0

        def count_k_palindromic(n: int, k: int) -> int:
            count = 0
            for i in range(10**(n-1), 10**n):
                if is_k_palindromic(i, k):
                    count += 1
            return count

        def get_digit_counts(n: int) -> list:
            digit_counts = [0]*10
            for i in range(10**(n-1), 10**n):
                for digit in str(i):
                    digit_counts[int(digit)] += 1
            return digit_counts

        if n == 1:
            return sum(1 for i in range(1, 10) if i % k == 0)

        count = 0
        digit_counts = get_digit_counts(n)
        for i in range(10**(n-1), 10**n):
            digits = [int(d) for d in str(i)]
            if len(set(digits)) == 1:
                count += 1 if i % k == 0 else 0
            else:
                odd_counts = sum(digits.count(d) % 2 for d in set(digits))
                if odd_counts <= 1:
                    rearranged_num = int(''.join(sorted(str(i)))[:n//2] + 
                                          ''.join(sorted(str(i)))[:n//2][::-1] 
                                          if n % 2 == 0 else 
                                          ''.join(sorted(str(i)))[:n//2+1] + 
                                          ''.join(sorted(str(i)))[:n//2][::-1])
                    if rearranged_num % k == 0 and len(str(rearranged_num)) == n:
                        count += 1
        return count

