class SegmentTree:
    def __init__(self, n):
        self.tree = [0] * (4 * n)
        self.lazy = [0] * (4 * n)
        self.n = n

    def build(self, colors, node, start, end):
        if start == end:
            self.tree[node] = 1 if colors[start] != colors[(start + 1) % self.n] else 0
        else:
            mid = (start + end) // 2
            self.build(colors, 2 * node, start, mid)
            self.build(colors, 2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, node, start, end, left, right, val):
        if self.lazy[node] != 0:
            self.tree[node] = (end - start + 1) * self.lazy[node]
            if start != end:
                self.lazy[2 * node] = self.lazy[node]
                self.lazy[2 * node + 1] = self.lazy[node]
            self.lazy[node] = 0

        if start > right or end < left:
            return

        if start >= left and end <= right:
            self.tree[node] = (end - start + 1) * val
            if start != end:
                self.lazy[2 * node] = val
                self.lazy[2 * node + 1] = val
            return

        mid = (start + end) // 2
        self.update(2 * node, start, mid, left, right, val)
        self.update(2 * node + 1, mid + 1, end, left, right, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, node, start, end, left, right):
        if self.lazy[node] != 0:
            self.tree[node] = (end - start + 1) * self.lazy[node]
            if start != end:
                self.lazy[2 * node] = self.lazy[node]
                self.lazy[2 * node + 1] = self.lazy[node]
            self.lazy[node] = 0

        if start > right or end < left:
            return 0

        if start >= left and end <= right:
            return self.tree[node]

        mid = (start + end) // 2
        return self.query(2 * node, start, mid, left, right) + self.query(2 * node + 1, mid + 1, end, left, right)


