    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        count = Counter(nums)
        max_freq = max(count.values())

        if numOperations == 0:
            return max_freq

        unique_nums = list(count.keys())
        heapq.heapify(unique_nums)

        res = 0
        while unique_nums:
            num = heapq.heappop(unique_nums)
