class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        n = len(word)
        base = n // numFriends
        extra = n % numFriends
        result = ""
        for i in range(numFriends):
            if i < extra:
                result += word[i * (base + 1):(i + 1) * (base + 1)]
            else:
                result += word[extra * (base + 1) + i * base:extra * (base + 1) + (i + 1) * base]
