class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        max_num = max(nums)

        # Initialize a sieve to mark multiples of each GCD value
        sieve = [0] * (max_num + 1)

        # Calculate the GCD of all pairs of numbers in the array
        for i in range(n):
            for j in range(i + 1, n):
                g = gcd(nums[i], nums[j])
                sieve[g] += 1

        # Calculate cumulative counts
        for i in range(1, max_num + 1):
            sieve[i] += sieve[i - 1]

        # For each query, find the element at the specified index in gcd_pairs
        answer = []
        for query in queries:
            # Find the GCD value at the specified index
            for g in range(max_num + 1):
                if sieve[g] > query:
                    answer.append(g)
                    break

        return answer

