                if rank[rootx] > rank[rooty]:
                    parent[rooty] = rootx
                else:
                    parent[rootx] = rooty
                    if rank[rootx] == rank[rooty]:
                        rank[rooty] += 1

        # Initialize distance array
        distance = [float('inf')] * n
        distance[0] = 0

        # Initialize result array
        result = []

        # Process queries
        for u, v in queries:
            union(u, v)

            # Update distance array
            new_distance = [float('inf')] * n
            new_distance[0] = 0
            for i in range(n - 1):
                new_distance[i + 1] = min(new_distance[i + 1], new_distance[i] + 1)
            for i in range(n - 2, -1, -1):
                new_distance[i] = min(new_distance[i], new_distance[i + 1] + 1)

            # Update distance array based on Union-Find
            for i in range(n):
