class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootx = find(x)
            rooty = find(y)
            if rootx != rooty:
                if rank[rootx] > rank[rooty]:
                    parent[rooty] = rootx
                else:
                    parent[rootx] = rooty
                    if rank[rootx] == rank[rooty]:
                        rank[rooty] += 1

        distance = [float('inf')] * n
        distance[0] = 0
        result = []

        for u, v in queries:
            union(u, v)
            for i in range(n):
                if find(i) == find(0):
                    distance[i] = min(distance[i], distance[0] + abs(i - 0))
            result.append(distance[n - 1])

        return result

