            set_bits = bin_i.count('1')
            for j in range(k + 1):
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[set_bits][j - 1]) % MOD
                if i < set_bits:
                    dp[i][j] = (dp[i][j] + dp[i][j]) % MOD
                dp[i][j] = (dp[i][j] + (1 if set_bits == 1 else 0)) % MOD

