    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = int(s, 2)
        memo = {}

        def dp(x, k):
            if (x, k) in memo:
                return memo[(x, k)]
            if x == 1:
                return 1
            if k == 0:
                return 0
            set_bits = bin(x).count('1')
            res = dp(set_bits, k - 1)
            memo[(x, k)] = res
            return res

