class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7
        n = len(num)
        digit_counts = Counter(num)

        total_permutations = factorial(n)
        for count in digit_counts.values():
            total_permutations *= pow(factorial(count), -1, MOD)

        even_sum = sum(int(digit) for i, digit in enumerate(num) if i % 2 == 0)
        odd_sum = sum(int(digit) for i, digit in enumerate(num) if i % 2 != 0)

        if even_sum != odd_sum:
            return 0

        numerator = 0
        for k in range(n + 1):
            if (even_sum + k) * 2 == n * int(num[0]):
                numerator += (factorial(n) * pow(factorial(k), -1, MOD) * 
                             pow(factorial(n - k), -1, MOD) * 
                             pow(2, k, MOD)) % MOD
                numerator %= MOD

        return (total_permutations * pow(2, -1, MOD) * (numerator)) % MOD

