class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)

        # Calculate prefix GCD array
        prefix_gcd = [0]*n
        prefix_gcd[0] = nums[0]
        for i in range(1, n):
            prefix_gcd[i] = gcd(prefix_gcd[i-1], nums[i])

        # Calculate suffix GCD array
        suffix_gcd = [0]*n
        suffix_gcd[n-1] = nums[n-1]
        for i in range(n-2, -1, -1):
            suffix_gcd[i] = gcd(suffix_gcd[i+1], nums[i])

        def lcm(a, b):
            return a * b // gcd(a, b)

        res = nums[0] if n == 1 else reduce(lcm, nums)

        for i in range(n):
            # Calculate GCD and LCM after removing the element at index i
            if i == 0:
                g = suffix_gcd[1]
            elif i == n-1:
                g = prefix_gcd[n-2]
            else:
                g = gcd(prefix_gcd[i-1], suffix_gcd[i+1])

            if i == 0:
                l = reduce(lcm, nums[1:])
            elif i == n-1:
                l = reduce(lcm, nums[:-1])
            else:
                l = lcm(prefix_gcd[i-1], suffix_gcd[i+1])

            res = max(res, l * g)

        return res

