class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online_users = set(range(numberOfUsers))
        offline_users = {}

        for event in events:
            if event[0] == "MESSAGE":
                timestamp = int(event[1])
                mentions_str = event[2]
                tokens = mentions_str.split()

                for token in tokens:
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in online_users:
                            mentions[user] += 1
                    elif token.startswith("id"):
                        user_id = int(token[2:])
                        mentions[user_id] += 1

                # update online users
                new_offline_users = {}
                for user, time in offline_users.items():
                    if time <= timestamp:
                        online_users.add(user)
                        del online_users
                    else:
                        new_offline_users[user] = time
                offline_users = new_offline_users

            elif event[0] == "OFFLINE":
                timestamp = int(event[1])
                user_id = int(event[2])
                online_users.remove(user_id)
                offline_users[user_id] = timestamp + 60

        return mentions

