class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        degrees = [0] * n
        for u in range(n):
            degrees[u] = len(graph[u])

        edge_list = []
        for u in range(n):
            for v, w in graph[u]:
                if u < v:
                    edge_list.append((u, v, w))
        edge_list.sort(key=lambda x: x[2], reverse=True)

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootx = find(x)
            rooty = find(y)
            if rootx != rooty:
                if rank[rootx] > rank[rooty]:
                    parent[rooty] = rootx
                else:
                    parent[rootx] = rooty
                    if rank[rootx] == rank[rooty]: rank[rooty] += 1

        def is_connected(x, y):
            return find(x) == find(y)

        res = 0
        for u, v, w in edge_list:
            if degrees[u] < k and degrees[v] < k:
                res += w
                degrees[u] += 1
                degrees[v] += 1
                union(u, v)
        return res

