class Solution:
    def maxFreeTime(self, eventTime: int, startTime: List[int], endTime: List[int]) -> int:
        meetings = sorted(zip(startTime, endTime), key=lambda x: x[1])
        max_free_time = 0
        gaps = []
        if meetings[0][0] > 0:
            gaps.append(meetings[0][0])
        for i in range(len(meetings) - 1):
            gap = meetings[i+1][0] - meetings[i][1]
            if gap > 0:
                gaps.append(gap)
        if meetings[-1][1] < eventTime:
            gaps.append(eventTime - meetings[-1][1])
        max_free_time = max(gaps) if gaps else 0
        for reschedule_index in range(len(meetings)):
            left, right = meetings[reschedule_index][1], eventTime - (meetings[reschedule_index][1] - meetings[reschedule_index][0])
            while left < right:
                mid = (left + right) // 2
                new_meeting = (mid, mid + (meetings[reschedule_index][1] - meetings[reschedule_index][0]))
                new_meetings = meetings[:reschedule_index] + [new_meeting] + meetings[reschedule_index+1:]
                new_gaps = []
                if new_meetings[0][0] > 0:
                    new_gaps.append(new_meetings[0][0])
                for i in range(len(new_meetings) - 1):
                    gap = new_meetings[i+1][0] - new_meetings[i][1]
                    if gap > 0:
                        new_gaps.append(gap)
                if new_meetings[-1][1] < eventTime:
                    new_gaps.append(eventTime - new_meetings[-1][1])
                if new_gaps and max(new_gaps) > max_free_time:
                    left = mid + 1
                else:
                    right = mid
            new_meeting = (left, left + (meetings[reschedule_index][1] - meetings[reschedule_index][0]))
            new_meetings = meetings[:reschedule_index] + [new_meeting] + meetings[reschedule_index+1:]
            new_gaps = []
            if new_meetings[0][0] > 0:
                new_gaps.append(new_meetings[0][0])
            for i in range(len(new_meetings) - 1):
                gap = new_meetings[i+1][0] - new_meetings[i][1]
                if gap > 0:
                    new_gaps.append(gap)
            if new_meetings[-1][1] < eventTime:
                new_gaps.append(eventTime - new_meetings[-1][1])
            if new_gaps:
