class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        """
        Traverse the grid in a zigzag pattern while skipping every alternate cell.

        Args:
        grid (List[List[int]]): A 2D array of positive integers.

        Returns:
        List[int]: An array of integers containing the values of the cells visited during the zigzag traversal with skips.
        """
        result = []
        for i in range(len(grid)):
            # For even rows, iterate over columns with a step size of 2
            if i % 2 == 0:
                for j in range(0, len(grid[0]), 2):
                    result.append(grid[i][j])
            # For odd rows, iterate over columns in reverse with a step size of 2
            else:
                for j in range(len(grid[0]) - 1, -1, -2):
                    result.append(grid[i][j])
        return result

